  [97972] = { "Campeggio 101: Sartoria", nil, "La Sartoria è un mestiere sorprendentemente valido su cui investire, e di certo ti servirà bene.\n\nConosco qualcuno che può insegnarti a fabbricare un Faction Banner per il tuo accampamento, se hai l'abilità necessaria. Ispirazione e morale sono fondamentali per vincere su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, nil, 0xde7f398c, nil, 0x49663bd1, nil, nil, ".m.mm" },
